    "type": "medinoise",
    "versets_count": 129,
    "theme": "La rupture des pactes trahis par les polythéistes, l'expédition de Tabūk et le dévoilement des hypocrites, la zakāt et ses bénéficiaires, et le repentir accueilli — jusqu'aux trois laissés en arrière que Dieu ramène à Lui",
    "note_pedagogique": "L'unique sourate du Coran sans basmala — révélée comme un ultimatum après des trahisons de pactes, elle ne s'ouvre pas au nom de la miséricorde. Pourtant elle porte le nom du Repentir : elle culmine sur le pardon accordé aux trois compagnons restés en arrière à Tabūk (v.118), et s'achève sur le portrait le plus tendre du Prophète : « ardemment soucieux de vous, compatissant et miséricordieux envers les croyants ».",
